package com.masterlearning.platform.modules.program.entity;
import com.masterlearning.platform.common.entity.BaseEntity; import com.masterlearning.platform.modules.organization.entity.Organization; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="programs") public class Program extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=180) private String title; @Column(nullable=false,unique=true,length=220) private String slug; @Column(length=3000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ProgramStatus status=ProgramStatus.DRAFT; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organization_id") private Organization organization; protected Program(){} public Program(String t,String s,String d,Organization o){title=t;slug=s;description=d;organization=o;} public UUID getId(){return id;} public String getTitle(){return title;} public String getSlug(){return slug;} public String getDescription(){return description;} public ProgramStatus getStatus(){return status;} public void publish(){status=ProgramStatus.PUBLISHED;} }